package com.tiktokinsight.admin.api;
import com.tiktokinsight.admin.application.AdministrationService;import com.tiktokinsight.admin.domain.*;import com.tiktokinsight.analysis.domain.AnalysisJob;import com.tiktokinsight.auth.application.AccessPrincipal;import com.tiktokinsight.auth.domain.UserRole;import com.tiktokinsight.common.api.*;import com.tiktokinsight.common.logging.RequestIdFilter;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.constraints.NotNull;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin") public class AdministrationController {private final AdministrationService service;public AdministrationController(AdministrationService service){this.service=service;}@GetMapping("/dashboard")public ApiResponse<AdminDashboard> dashboard(){return ApiResponse.success(service.dashboard(),RequestIdFilter.currentRequestId());}@GetMapping("/users")public ApiResponse<PageResponse<AdminUser>> users(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.success(service.users(page,pageSize),RequestIdFilter.currentRequestId());}@PutMapping("/users/{id}/role")public ApiResponse<AdminUser> role(@PathVariable long id,@RequestBody RoleRequest body,@AuthenticationPrincipal AccessPrincipal p,HttpServletRequest h){return ApiResponse.success(service.changeRole(id,body.role(),p,h),RequestIdFilter.currentRequestId());}@GetMapping("/jobs/analysis")public ApiResponse<PageResponse<AnalysisJob>> jobs(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.success(service.analysisJobs(page,pageSize),RequestIdFilter.currentRequestId());}@PostMapping("/jobs/analysis/recalculate")public ApiResponse<Integer> recalculate(@AuthenticationPrincipal AccessPrincipal p,HttpServletRequest h){return ApiResponse.success(service.recalculate(p,h),RequestIdFilter.currentRequestId());}public record RoleRequest(@NotNull UserRole role) {}}
